// Sound playback over real audio assets.
//
// The cues in /public/sfx are generated by `npm run sfx` (tools/generate_sfx.py)
// and streamed as ordinary files. Preloading and pooling them keeps the first
// play of a round instant -- a slot that lags on the reel-stop click feels
// broken even when the maths is fine.
//
// Rules this module enforces:
//   * nothing plays before the player interacts (browser autoplay policy),
//   * mute and volume persist across sessions,
//   * overlapping cues mix instead of cutting each other off,
//   * a missing file is a no-op, never a thrown error mid-round.

const BASE = "/sfx";

export type SoundName =
  | "spin"
  | "reel-stop-1"
  | "reel-stop-2"
  | "reel-stop-3"
  | "reel-stop-4"
  | "reel-stop-5"
  | "symbol-tick"
  | "line-win"
  | "scatter"
  | "big-win"
  | "coin"
  | "button"
  | "count-tick"
  | "anticipation";

const ALL: SoundName[] = [
  "spin",
  "reel-stop-1",
  "reel-stop-2",
  "reel-stop-3",
  "reel-stop-4",
  "reel-stop-5",
  "symbol-tick",
  "line-win",
  "scatter",
  "big-win",
  "coin",
  "button",
  "count-tick",
  "anticipation",
];

const STORAGE_KEY = "luminara.sound";

interface Settings {
  muted: boolean;
  volume: number;
}

const DEFAULTS: Settings = { muted: false, volume: 0.55 };

function readSettings(): Settings {
  if (typeof window === "undefined") return DEFAULTS;
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return DEFAULTS;
    const parsed = JSON.parse(raw) as Partial<Settings>;
    return {
      muted: Boolean(parsed.muted),
      volume: typeof parsed.volume === "number" ? clamp(parsed.volume, 0, 1) : DEFAULTS.volume,
    };
  } catch {
    return DEFAULTS;
  }
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function persist(settings: Settings): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch {
    // Private browsing can refuse storage; audio still works for the session.
  }
}

let settings = readSettings();
let unlocked = false;

// Two banks so a cue can overlap the previous one without cutting it off
// (a reel-stop landing while the win chime is still ringing).
const POOL_SIZE = 4;
const banks: HTMLAudioElement[][] = [];
const nextIndex = new Map<SoundName, number>();

function ensureBank(): HTMLAudioElement[][] | null {
  if (typeof window === "undefined" || typeof Audio === "undefined") return null;
  if (banks.length > 0) return banks;

  for (let i = 0; i < POOL_SIZE; i += 1) {
    banks.push([]);
  }
  ALL.forEach((name) => nextIndex.set(name, 0));
  return banks;
}

/** Warms the cache so the first spin has no loading hitch. */
export function preload(): void {
  if (typeof window === "undefined") return;
  const bank = ensureBank();
  if (!bank) return;

  ALL.forEach((name) => {
    const audio = new Audio(`${BASE}/${name}.wav`);
    audio.preload = "auto";
    audio.volume = 0;
    // Silence errors: a 404 on an optional cue must stay invisible.
    audio.addEventListener("error", () => undefined);
    bank[0].push(audio);
  });
}

/**
 * Starts playback, swallowing both failure modes.
 *
 * `play()` rejects when the browser blocks autoplay, and throws synchronously
 * in environments with no media stack at all. A missing or blocked track must
 * never break the page, so both are caught.
 */
function safePlay(audio: HTMLAudioElement): void {
  try {
    const result = audio.play();
    if (result && typeof result.catch === "function") {
      result.catch(() => undefined);
    }
  } catch {
    // No media support: audio is simply unavailable here.
  }
}

/** Called from a user gesture so later playback is allowed. */
export function unlock(): void {
  if (unlocked) return;
  preload();
  unlocked = true;
  // Starting the bed here means the music begins the moment the player first
  // touches the game, which is also the first moment a browser will allow it.
  if (musicWanted) setMusicEnabled(true);
}

function poolFor(name: SoundName): HTMLAudioElement | null {
  const bank = ensureBank();
  if (!bank) return null;

  const index = nextIndex.get(name) ?? 0;
  nextIndex.set(name, (index + 1) % POOL_SIZE);

  // The preload pass filled bank 0; reuse it rather than refetching.
  const slot = bank[index % POOL_SIZE];
  const existing = slot[index];
  if (existing && existing.dataset.name === name) return existing;

  const audio = new Audio(`${BASE}/${name}.wav`);
  audio.preload = "auto";
  audio.dataset.name = name;
  slot[index] = audio;
  return audio;
}

// --- background music ------------------------------------------------------

const MUSIC_PATH = `${BASE}/music-loop.wav`;

let music: HTMLAudioElement | null = null;
let musicWanted = false;

/**
 * Starts or stops the looping bed.
 *
 * The track is a seamless 30-second loop, so `loop` gives continuous playback
 * with no gap and no re-trigger. It sits at its own level under the cues.
 */
export function setMusicEnabled(enabled: boolean): void {
  musicWanted = enabled;
  if (typeof window === "undefined" || typeof Audio === "undefined") return;

  if (!enabled) {
    music?.pause();
    return;
  }

  if (!music) {
    music = new Audio(MUSIC_PATH);
    music.loop = true;
    music.preload = "auto";
    music.addEventListener("error", () => undefined);
  }

  applyMusicVolume();
  safePlay(music);
}

export function isMusicEnabled(): boolean {
  return musicWanted;
}

const MUSIC_KEY = "luminara.music";

export function readMusicPreference(): boolean {
  if (typeof window === "undefined") return true;
  try {
    return window.localStorage.getItem(MUSIC_KEY) !== "off";
  } catch {
    return true;
  }
}

export function persistMusicPreference(enabled: boolean): void {
  try {
    window.localStorage.setItem(MUSIC_KEY, enabled ? "on" : "off");
  } catch {
    // Storage may be unavailable; the session still works.
  }
}

/** Music runs at a fraction of the master volume so cues stay clear. */
const MUSIC_LEVEL = 0.3;

function applyMusicVolume(): void {
  // Guarded: an environment without a real media element (tests, some
  // embedded webviews) must not turn a mute toggle into a crash.
  if (!music) return;
  try {
    music.volume = settings.muted ? 0 : MUSIC_LEVEL;
  } catch {
    // Nothing to do: the bed simply stays at whatever level it had.
  }
}

export function isMuted(): boolean {
  return settings.muted;
}

export function getVolume(): number {
  return settings.volume;
}

export function setMuted(muted: boolean): void {
  settings = { ...settings, muted };
  persist(settings);
  applyMusicVolume();
}

export function toggleMuted(): boolean {
  setMuted(!settings.muted);
  return settings.muted;
}

export function setVolume(volume: number): void {
  settings = { ...settings, volume: clamp(volume, 0, 1) };
  persist(settings);
}

export interface PlayOptions {
  /** Multiplies the master volume for this one cue. */
  gain?: number;
  /** Small random pitch shift keeps repeats from sounding mechanical. */
  detune?: number;
  /** Start offset in seconds. */
  delay?: number;
}

/**
 * Plays a cue. Safe before any gesture: the browser simply produces no sound
 * until `unlock()` has run.
 */
export function play(name: SoundName, options: PlayOptions = {}): void {
  if (settings.muted) return;
  const audio = poolFor(name);
  if (!audio) return;

  const gain = clamp((options.gain ?? 1) * settings.volume, 0, 1);
  const detune = options.detune ?? 0;
  // 12 semitones at 1.0; a couple of percent either way is enough variety.
  const rate = detune === 0 ? 1 : 2 ** (detune / 12);

  audio.volume = gain;
  audio.playbackRate = rate;
  audio.currentTime = 0;

  if (options.delay && options.delay > 0) {
    window.setTimeout(() => {
      safePlay(audio);
    }, options.delay * 1000);
    return;
  }

  safePlay(audio);
}

/** Plays a reel-stop cue; the pitch climbs slightly for each reel in turn. */
export function playReelStop(reelIndex: number): void {
  const names: SoundName[] = [
    "reel-stop-1",
    "reel-stop-2",
    "reel-stop-3",
    "reel-stop-4",
    "reel-stop-5",
  ];
  const name = names[clamp(reelIndex, 0, names.length - 1)];
  play(name, { gain: 0.9, detune: (Math.random() - 0.5) * 0.6 });
}

/** Plays several cues in sequence; used for winning-line stings. */
export function playSequence(name: SoundName, count: number, spacing: number, gain = 1): void {
  for (let i = 0; i < count; i += 1) {
    play(name, { gain, delay: i * spacing });
  }
}

/** True once the browser will actually let audio through. */
export function isUnlocked(): boolean {
  return unlocked;
}
